INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Middleware immer für Datenbankzugriff nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Direkte Verbindungen möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe übernimmt Middleware in einem System?', 3, '[{"text": "Verbindung zwischen Anwendungen", "correct": true, "because": "Schnittstellen vermitteln"}, {"text": "Grafische Oberfläche", "correct": false, "because": "Nicht primär"}, {"text": "Hardwaresteuerung", "correct": false, "because": "Andere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen Middleware für verteilte Systeme nützlich?', 5, '[{"text": "Datenintegration", "correct": true, "because": "Verschiedene Quellen verbinden"}, {"text": "Kommunikationsschnittstellen", "correct": true, "because": "Heterogene Systeme verknüpfen"}, {"text": "Hohe Grafikleistung", "correct": false, "because": "Irrelevant"}, {"text": "Kostenlosigkeit", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Middleware abstrahiert Datenbankzugriff. b) Sie ersetzt Betriebssysteme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, ergänzt nur"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl von Middleware für eine Datenbank?', 4, '[{"text": "Kompatibilität", "correct": false, "because": "Muss zu System passen"}, {"text": "Schnittstellen", "correct": false, "because": "Kern der Funktion"}, {"text": "Gaming-Features", "correct": true, "because": "Irrelevant für Datenbankzugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Middleware die Performance immer verbessert?', 2, '[{"text": "Nein", "correct": true, "because": "Overhead möglich"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für eine Middleware bei APIs entscheidend?', 3, '[{"text": "Standardisierte Schnittstellen", "correct": true, "because": "Interoperabilität sichern"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Sekundär"}, {"text": "Einfache Installation", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Middleware für Datenbankzugriff?', 5, '[{"text": "Abstraktion", "correct": true, "because": "Vereinfacht Entwicklung"}, {"text": "Flexibilität", "correct": true, "because": "Verschiedene DBs anbinden"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht zwangsläufig"}, {"text": "Grafische Tools", "correct": false, "because": "Nicht Kernaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Middleware vereinfacht Schnittstellen. b) Sie ist nur für große Firmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch für kleine Systeme"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Middleware in einem kleinen Projekt?', 4, '[{"text": "Datenbankanbindung", "correct": false, "because": "Kernfunktion"}, {"text": "Skalierbarkeit", "correct": false, "because": "Zukunftssicherheit"}, {"text": "High-End-Clustering", "correct": true, "because": "Überdimensioniert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Middleware nur für Cloud-Systeme geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokal nützlich"}, {"text": "Ja", "correct": false, "because": "Breiter Einsatzbereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für Middleware in einem ERP-System wichtig?', 4, '[{"text": "Integration", "correct": true, "because": "Module verbinden"}, {"text": "Sicherheit", "correct": true, "because": "Daten schützen"}, {"text": "Hohe Latenz", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Middleware die Entwicklung erschwert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sie vereinfacht oft"}, {"text": "Ja", "correct": false, "because": "Komplexität reduziert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Middleware für eine Web-App?', 3, '[{"text": "Schnelle Datenübertragung", "correct": true, "because": "Effizienz erhöhen"}, {"text": "Maximale Kapazität", "correct": false, "because": "Sekundär"}, {"text": "Einfache GUI", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Middleware verbindet heterogene Systeme. b) Sie ersetzt Datenbanken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, ergänzt nur"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat Middleware?', 5, '[{"text": "Zusätzliche Komplexität", "correct": true, "because": "Extra Schicht im System"}, {"text": "Möglicher Overhead", "correct": true, "because": "Performanceeinbußen"}, {"text": "Hohe Sicherheit", "correct": false, "because": "Kein Nachteil"}, {"text": "Einfache Wartung", "correct": false, "because": "Nicht immer gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Middleware für eine kleine Datenbank unwichtig?', 3, '[{"text": "Kompatibilität", "correct": false, "because": "Muss passen"}, {"text": "Datenfluss", "correct": false, "because": "Kernaufgabe"}, {"text": "Massive Skalierung", "correct": true, "because": "Nicht nötig bei Kleinprojekten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützt Middleware nur SQL-Datenbanken?', 3, '[{"text": "Nein", "correct": true, "because": "Auch NoSQL und mehr"}, {"text": "Ja", "correct": false, "because": "Breitere Unterstützung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Middleware auch Sicherheitsfunktionen bietet?', 2, '[{"text": "Ja", "correct": true, "because": "Authentifizierung möglich"}, {"text": "Nein", "correct": false, "because": "Oft enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Middleware-Funktion wähle ich für eine REST-API?', 4, '[{"text": "API-Gateway", "correct": true, "because": "Verwaltet Anfragen effizient"}, {"text": "Direkte DB-Verbindung", "correct": false, "because": "Zu tief"}, {"text": "Grafische Oberfläche", "correct": false, "because": "Nicht nötig"}]');
